1	package main
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"text/tabwriter"
8	
9		"github.com/integrio-intropy/intropy-cli/internal/template"
10		"github.com/spf13/cobra"
11	)
12	
13	type intListFlags struct {
14		output string
15	}
16	
17	var intListOpts intListFlags
18	
19	var intListCmd = &cobra.Command{
20		Use:   "list [dir]",
21		Short: "List scaffolded integrations under a directory",
22		Long: "Walk the directory tree from dir (default: the current directory) and list every project carrying a " +
23			template.ScaffoldRelPath + " record written by `int create`. " +
24			"Matched projects are not descended into, and .git, .intropy, node_modules, bin and dist are skipped. " +
25			"Use --output json for a machine-readable document including the pinned source and scaffold values.",
26		Args: cobra.MaximumNArgs(1),
27		RunE: func(cmd *cobra.Command, args []string) error {
28			if err := validateOutputFlag(intListOpts.output, "json", "plain"); err != nil {
29				return err
30			}
31			root := "."
32			if len(args) == 1 {
33				root = args[0]
34			}
35			if info, err := os.Stat(root); err != nil {
36				return fmt.Errorf("list: %w", err)
37			} else if !info.IsDir() {
38				return newUsageErrorf("list: %s is not a directory", root)
39			}
40	
41			entries, warnings := template.ListScaffolds(root)
42			for _, w := range warnings {
43				fmt.Fprintln(cmd.ErrOrStderr(), "warning:", w)
44			}
45	
46			if intListOpts.output == "json" {
47				if entries == nil {
48					entries = []template.ScaffoldEntry{}
49				}
50				enc := json.NewEncoder(cmd.OutOrStdout())
51				enc.SetIndent("", "  ")
52				return enc.Encode(entries)
53			}
54	
55			if len(entries) == 0 {
56				fmt.Fprintln(cmd.ErrOrStderr(), "No scaffolded integrations found.")
57				return nil
58			}
59	
60			tw := tabwriter.NewWriter(cmd.OutOrStdout(), 0, 0, 2, ' ', 0)
61			fmt.Fprintln(tw, "PATH\tTEMPLATE\tVERSION")
62			for _, e := range entries {
63				fmt.Fprintf(tw, "%s\t%s\t%s\n", e.Path, e.Template, e.Version)
64			}
65			return tw.Flush()
66		},
67	}
68	
69	func init() {
70		f := intListCmd.Flags()
71		f.StringVarP(&intListOpts.output, "output", "o", "plain", "output format: plain or json")
72		intCmd.AddCommand(intListCmd)
73	}
