1	package dashboard
2	
3	import (
4		"encoding/json"
5		"net/http"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10	
11		"github.com/integrio-intropy/intropy-cli/internal/template"
12	)
13	
14	// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
15	// the detail endpoint returns, so a huge file cannot bloat a response.
16	const maxDocBytes = 128 * 1024
17	
18	// apiServer holds the request-independent state for the JSON API.
19	type apiServer struct {
20		root    string
21		version string
22	}
23	
24	// fileDoc is a text document surfaced in an integration's detail view.
25	type fileDoc struct {
26		Name    string `json:"name"`
27		Content string `json:"content"`
28	}
29	
30	// integrationDetail is a single integration plus best-effort, on-disk
31	// enrichment. Every enrichment field is optional and absent when the
32	// corresponding file or directory does not exist.
33	type integrationDetail struct {
34		template.ScaffoldEntry
35		Agents         *fileDoc `json:"agents,omitempty"`
36		Readme         *fileDoc `json:"readme,omitempty"`
37		DaprComponents []string `json:"daprComponents,omitempty"`
38		PipelineSteps  []string `json:"pipelineSteps,omitempty"`
39	}
40	
41	// newHandler wires the API routes and the SPA static handler onto a mux.
42	func newHandler(root, version string) (http.Handler, error) {
43		api := &apiServer{root: root, version: version}
44		static, err := staticHandler()
45		if err != nil {
46			return nil, err
47		}
48	
49		mux := http.NewServeMux()
50		mux.HandleFunc("GET /api/health", api.health)
51		mux.HandleFunc("GET /api/integrations", api.listIntegrations)
52		mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
53		mux.Handle("/", static)
54		return mux, nil
55	}
56	
57	func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
58		writeJSON(w, http.StatusOK, map[string]string{
59			"status":  "ok",
60			"version": s.version,
61		})
62	}
63	
64	// listIntegrations mirrors `int list -o json`: a flat array of scaffold
65	// entries, always an array (never null) even when empty.
66	func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
67		entries, _ := template.ListScaffolds(s.root)
68		if entries == nil {
69			entries = []template.ScaffoldEntry{}
70		}
71		writeJSON(w, http.StatusOK, entries)
72	}
73	
74	func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
75		want := strings.Trim(r.PathValue("path"), "/")
76		entries, _ := template.ListScaffolds(s.root)
77		for _, e := range entries {
78			if filepath.ToSlash(e.Path) == want {
79				writeJSON(w, http.StatusOK, s.enrich(e))
80				return
81			}
82		}
83		writeError(w, http.StatusNotFound, "integration not found: "+want)
84	}
85	
86	// enrich reads optional on-disk context for an integration. The entry's Path
87	// is already usable from the process working directory (see ListScaffolds), so
88	// it doubles as the project directory.
89	func (s *apiServer) enrich(e template.ScaffoldEntry) integrationDetail {
90		dir := e.Path
91		return integrationDetail{
92			ScaffoldEntry:  e,
93			Agents:         readDoc(dir, "AGENTS.md"),
94			Readme:         readDoc(dir, "README.md"),
95			DaprComponents: listNames(filepath.Join(dir, "local", "dapr-components")),
96			PipelineSteps:  listNames(filepath.Join(dir, "src", "Process", "Steps")),
97		}
98	}
99	
100	// readDoc returns the named text file's (possibly truncated) contents, or nil
101	// if it is absent or unreadable.
102	func readDoc(dir, name string) *fileDoc {
103		data, err := os.ReadFile(filepath.Join(dir, name))
104		if err != nil {
105			return nil
106		}
107		if len(data) > maxDocBytes {
108			data = data[:maxDocBytes]
109		}
110		return &fileDoc{Name: name, Content: string(data)}
111	}
112	
113	// listNames returns the sorted base names of the files directly under dir, or
114	// nil if dir is absent or unreadable.
115	func listNames(dir string) []string {
116		ents, err := os.ReadDir(dir)
117		if err != nil {
118			return nil
119		}
120		var names []string
121		for _, ent := range ents {
122			if !ent.IsDir() {
123				names = append(names, ent.Name())
124			}
125		}
126		sort.Strings(names)
127		return names
128	}
129	
130	func writeJSON(w http.ResponseWriter, status int, v any) {
131		w.Header().Set("Content-Type", "application/json; charset=utf-8")
132		w.WriteHeader(status)
133		enc := json.NewEncoder(w)
134		enc.SetIndent("", "  ")
135		_ = enc.Encode(v)
136	}
137	
138	func writeError(w http.ResponseWriter, status int, msg string) {
139		writeJSON(w, status, map[string]string{"error": msg})
140	}
