1	package template
2	
3	import (
4		"fmt"
5		"io/fs"
6		"os"
7		"path/filepath"
8	)
9	
10	// listSkipDirs are directory names never worth descending into when scanning
11	// for projects: VCS metadata, the project record dir itself, dependency
12	// trees, and build output.
13	var listSkipDirs = map[string]bool{
14		".git":         true,
15		".intropy":     true,
16		"node_modules": true,
17		"bin":          true,
18		"dist":         true,
19	}
20	
21	// ScaffoldEntry is one project found by ListScaffolds: the directory holding
22	// the record plus the record itself. The embedded Scaffold flattens into the
23	// JSON document so each entry is self-describing for machine consumers.
24	type ScaffoldEntry struct {
25		Path string `json:"path"`
26		Scaffold
27	}
28	
29	// ListScaffolds walks the tree rooted at root and returns an entry for every
30	// directory that contains .intropy/scaffold.json, in lexical walk order.
31	// Paths are reported as WalkDir yields them (root-prefixed), so with a
32	// relative root they stay usable from the caller's working directory. A
33	// matched directory is not descended into — projects do not nest. Unreadable
34	// directories and malformed records become warnings rather than failures so
35	// one bad project cannot hide the rest.
36	func ListScaffolds(root string) (entries []ScaffoldEntry, warnings []error) {
37		walkErr := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
38			if err != nil {
39				warnings = append(warnings, err)
40				return nil
41			}
42			if !d.IsDir() {
43				return nil
44			}
45			if path != root && listSkipDirs[d.Name()] {
46				return fs.SkipDir
47			}
48	
49			record := filepath.Join(path, filepath.FromSlash(ScaffoldRelPath))
50			if _, err := os.Stat(record); err != nil {
51				if !os.IsNotExist(err) {
52					warnings = append(warnings, fmt.Errorf("stat %s: %w", record, err))
53				}
54				return nil
55			}
56			s, err := LoadScaffold(record)
57			if err != nil {
58				// Still a project root — don't descend looking for more.
59				warnings = append(warnings, err)
60				return fs.SkipDir
61			}
62			entries = append(entries, ScaffoldEntry{Path: path, Scaffold: *s})
63			return fs.SkipDir
64		})
65		if walkErr != nil {
66			warnings = append(warnings, walkErr)
67		}
68		return entries, warnings
69	}
