1	// Types mirror the Go JSON contract served by `intropy int run`
2	// (internal/dashboard). Integration matches template.ScaffoldEntry;
3	// IntegrationDetail adds the best-effort on-disk enrichment.
4	
5	export interface Integration {
6	  path: string
7	  schemaVersion: number
8	  template: string
9	  owner: string
10	  repo: string
11	  version: string
12	  values: Record<string, unknown>
13	}
14	
15	export interface FileDoc {
16	  name: string
17	  content: string
18	}
19	
20	export interface IntegrationDetail extends Integration {
21	  agents?: FileDoc
22	  readme?: FileDoc
23	  daprComponents?: string[]
24	  pipelineSteps?: string[]
25	}
26	
27	export interface Health {
28	  status: string
29	  version: string
30	}
31	
32	async function getJSON<T>(url: string): Promise<T> {
33	  const res = await fetch(url)
34	  if (!res.ok) {
35	    let message = `${res.status} ${res.statusText}`
36	    try {
37	      const body = (await res.json()) as { error?: string }
38	      if (body?.error) message = body.error
39	    } catch {
40	      // response had no JSON error body; keep the status line
41	    }
42	    throw new Error(message)
43	  }
44	  return (await res.json()) as T
45	}
46	
47	export const api = {
48	  listIntegrations: () => getJSON<Integration[]>('/api/integrations'),
49	  getIntegration: (path: string) =>
50	    getJSON<IntegrationDetail>(`/api/integrations/${path}`),
51	  health: () => getJSON<Health>('/api/health'),
52	}
