13	func writeScaffold(t *testing.T, dir, tmpl, version string) {
14		t.Helper()
15		intropyDir := filepath.Join(dir, ".intropy")
16		if err := os.MkdirAll(intropyDir, 0o755); err != nil {
17			t.Fatal(err)
18		}
19		body := `{"schemaVersion":1,"template":"` + tmpl + `","owner":"integrio-intropy","repo":"intropy-templates","version":"` + version + `","values":{"appId":"int1"}}` + "\n"
20		if err := os.WriteFile(filepath.Join(intropyDir, "scaffold.json"), []byte(body), 0o644); err != nil {
21			t.Fatal(err)
22		}
23	}
24	
25	func testHandler(t *testing.T, root string) http.Handler {
26		t.Helper()
27		h, err := newHandler(root, "test")
28		if err != nil {
29			t.Fatalf("newHandler: %v", err)
30		}
31		return h
32	}
33	
34	func get(t *testing.T, h http.Handler, path string) *httptest.ResponseRecorder {
35		t.Helper()
36		rec := httptest.NewRecorder()
37		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, path, nil))
38		return rec
39	}
40	
41	func TestHealth(t *testing.T) {
42		rec := get(t, testHandler(t, t.TempDir()), "/api/health")
43		if rec.Code != http.StatusOK {
44			t.Fatalf("status = %d, want 200", rec.Code)
45		}
46		var body map[string]string
47		if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
48			t.Fatalf("body not JSON: %v", err)
49		}
50		if body["status"] != "ok" || body["version"] != "test" {
51			t.Errorf("unexpected health body: %v", body)
52		}
53	}
54	
55	func TestIntegrationsEmptyIsArray(t *testing.T) {
56		t.Chdir(t.TempDir())
57		rec := get(t, testHandler(t, "."), "/api/integrations")
58		if got := strings.TrimSpace(rec.Body.String()); got != "[]" {
59			t.Errorf("body = %q, want []", got)
60		}
61	}
62	
63	func TestIntegrationsPopulated(t *testing.T) {
64		tmp := t.TempDir()
65		t.Chdir(tmp)
66		writeScaffold(t, filepath.Join(tmp, "orders"), "hello-world", "v0.1.6")
67	
68		rec := get(t, testHandler(t, "."), "/api/integrations")
69		var entries []map[string]any
70		if err := json.Unmarshal(rec.Body.Bytes(), &entries); err != nil {
71			t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
72		}
73		if len(entries) != 1 {
74			t.Fatalf("entries = %d, want 1", len(entries))
75		}
76		if entries[0]["path"] != "orders" || entries[0]["template"] != "hello-world" {
77			t.Errorf("unexpected entry: %v", entries[0])
78		}
79	}
80	
81	func TestIntegrationDetail(t *testing.T) {
82		tmp := t.TempDir()
83		t.Chdir(tmp)
84		proj := filepath.Join(tmp, "orders")
85		writeScaffold(t, proj, "hello-world", "v0.1.6")
86		if err := os.WriteFile(filepath.Join(proj, "AGENTS.md"), []byte("# Agents\nhello"), 0o644); err != nil {
87			t.Fatal(err)
88		}
89	
90		rec := get(t, testHandler(t, "."), "/api/integrations/orders")
91		if rec.Code != http.StatusOK {
92			t.Fatalf("status = %d, want 200", rec.Code)
93		}
94		var detail map[string]any
95		if err := json.Unmarshal(rec.Body.Bytes(), &detail); err != nil {
96			t.Fatalf("body not JSON: %v", err)
97		}
98		if detail["template"] != "hello-world" {
99			t.Errorf("template = %v, want hello-world", detail["template"])
100		}
101		agents, ok := detail["agents"].(map[string]any)
102		if !ok {
103			t.Fatalf("expected agents enrichment, got %v", detail["agents"])
104		}
105		if !strings.Contains(agents["content"].(string), "hello") {
106			t.Errorf("agents content missing: %v", agents["content"])
107		}
108	}
109	
110	func TestIntegrationDetailNotFound(t *testing.T) {
111		t.Chdir(t.TempDir())
112		rec := get(t, testHandler(t, "."), "/api/integrations/nope")
113		if rec.Code != http.StatusNotFound {
114			t.Fatalf("status = %d, want 404", rec.Code)
115		}
116	}
117	
118	func TestSPAFallback(t *testing.T) {
119		h := testHandler(t, t.TempDir())
120		for _, path := range []string{"/", "/some/deep/route"} {
121			rec := get(t, h, path)
122			if rec.Code != http.StatusOK {
123				t.Errorf("%s: status = %d, want 200", path, rec.Code)
124			}
125			if ct := rec.Header().Get("Content-Type"); !strings.HasPrefix(ct, "text/html") {
126				t.Errorf("%s: content-type = %q, want text/html", path, ct)
127			}
128			if !strings.Contains(rec.Body.String(), "Intropy Dashboard") {
129				t.Errorf("%s: body is not index.html", path)
130			}
131		}
132	}
