// listIntegrations mirrors `int list -o json`: a flat array of scaffold
// entries, always an array (never null) even when empty.
func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
	entries, _ := template.ListScaffolds(s.root)
