// TestIntegrationsTreeFields checks the derived sidebar-tree coordinates: the
// integration is named after the directory carrying .intropy and its system
// is the parent directory, absent for projects directly under the root.
func TestIntegrationsTreeFields(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeScaffold(t, filepath.Join(tmp, "erp", "order-intake"), "hello-world", "v0.1.6")
	writeScaffold(t, filepath.Join(tmp, "erp", "invoice-export"), "hello-world", "v0.1.6")
	writeScaffold(t, filepath.Join(tmp, "standalone"), "hello-world", "v0.1.6")

	rec := get(t, testHandler(t, "."), "/api/integrations")
	var entries []map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &entries); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	if len(entries) != 3 {
		t.Fatalf("entries = %d, want 3", len(entries))
	}

	got := map[string]string{}
	for _, e := range entries {
		name, _ := e["name"].(string)
		system, _ := e["system"].(string)
		got[name] = system
	}
	want := map[string]string{
		"order-intake":   "erp",
		"invoice-export": "erp",
		"standalone":     "",
	}
	for name, system := range want {
		g, ok := got[name]
		if !ok {
			t.Errorf("missing entry named %q, got %v", name, got)
			continue
		}
		if g != system {
			t.Errorf("system for %q = %q, want %q", name, g, system)
		}
	}
}

