import { useState } from 'react'
import type { Integration } from '../api'

interface Props {
  integrations: Integration[] | null
  selected: string | null
  onSelect: (path: string) => void
  collapsed: boolean
  onToggle: () => void
}

export function Sidebar({
  integrations,
  selected,
  onSelect,
  collapsed,
  onToggle,
}: Props) {
  const [closedSystems, setClosedSystems] = useState<Set<string>>(
    () => new Set(),
  )

  const toggleSystem = (system: string) =>
    setClosedSystems((prev) => {
      const next = new Set(prev)
      if (next.has(system)) next.delete(system)
      else next.add(system)
      return next
    })

  const { systems, ungrouped } = groupBySystem(integrations ?? [])

  return (
    <aside className={'sidebar' + (collapsed ? ' collapsed' : '')}>
      <div className="sidebar-header">
        {!collapsed && (
          <span className="sidebar-title">
            Integrations
            {integrations && <span className="count">{integrations.length}</span>}
          </span>
        )}
        <button
          className="collapse-btn"
          onClick={onToggle}
          aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
          aria-expanded={!collapsed}
          title={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
        >
          {collapsed ? '»' : '«'}
        </button>
      </div>

      {!collapsed && integrations === null && (
        <p className="muted pad">Loading…</p>
      )}

      {!collapsed && integrations?.length === 0 && (
        <p className="muted pad">No scaffolded integrations found.</p>
      )}

      {collapsed ? (
        <ul className="int-list">
          {integrations?.map((it) => (
            <li key={it.path}>
              <button
                className={'int-item' + (it.path === selected ? ' active' : '')}
                onClick={() => onSelect(it.path)}
                title={`${it.name} — ${it.path}`}
              >
                <span className="int-initial">{initial(it.name)}</span>
              </button>
            </li>
          ))}
        </ul>
      ) : (
        <nav className="tree">
          {systems.map(({ system, items }) => {
            const open = !closedSystems.has(system)
            return (
              <div className="sys-group" key={system}>
                <button
                  className="sys-header"
                  onClick={() => toggleSystem(system)}
                  aria-expanded={open}
                >
                  <span className="sys-caret" aria-hidden>
                    {open ? '▾' : '▸'}
                  </span>
                  <span className="sys-name">{system}</span>
                  <span className="count">{items.length}</span>
                </button>
                {open && (
                  <ul className="int-list nested">
                    {items.map((it) => (
                      <IntegrationItem
                        key={it.path}
                        integration={it}
                        active={it.path === selected}
                        onSelect={onSelect}
                      />
                    ))}
                  </ul>
                )}
              </div>
            )
          })}
          {ungrouped.length > 0 && (
            <ul className="int-list">
              {ungrouped.map((it) => (
                <IntegrationItem
                  key={it.path}
                  integration={it}
                  active={it.path === selected}
                  onSelect={onSelect}
                />
              ))}
            </ul>
          )}
        </nav>
      )}
    </aside>
  )
}

function IntegrationItem({
  integration: it,
  active,
  onSelect,
}: {
  integration: Integration
  active: boolean
  onSelect: (path: string) => void
}) {
  return (
    <li>
      <button
        className={'int-item' + (active ? ' active' : '')}
        onClick={() => onSelect(it.path)}
      >
        <span className="int-name">{it.name}</span>
        <span className="int-path">{it.path}</span>
      </button>
    </li>
  )
}

// groupBySystem buckets integrations under their system folder, systems
// sorted alphabetically. Integrations without a system (scaffolded directly
// under the workspace root) come back separately and render at the top level.
function groupBySystem(integrations: Integration[]): {
  systems: { system: string; items: Integration[] }[]
  ungrouped: Integration[]
} {
  const bySystem = new Map<string, Integration[]>()
  const ungrouped: Integration[] = []
  for (const it of integrations) {
    if (!it.system) {
      ungrouped.push(it)
      continue
    }
    const items = bySystem.get(it.system) ?? []
    items.push(it)
    bySystem.set(it.system, items)
  }
  const systems = [...bySystem.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([system, items]) => ({ system, items }))
  return { systems, ungrouped }
}

function initial(name: string): string {
  return name.trim().charAt(0).toUpperCase() || '?'
}

