                {open && (
                  <ul className="int-list nested">
                    {items.map((it) => (
                      <IntegrationItem
                        key={it.path}
                        integration={it}
                        active={it.path === selected}
                        onSelect={onSelect}
                      />
                    ))}
                  </ul>
                )}
              </div>
            )
          })}
          {ungrouped.length > 0 && (
            <ul className="int-list">
              {ungrouped.map((it) => (
                <IntegrationItem
                  key={it.path}
                  integration={it}
                  active={it.path === selected}
                  onSelect={onSelect}
                />
              ))}
            </ul>
          )}
        </nav>
      )}
    </aside>
  )
}

function IntegrationItem({
  integration: it,
  active,
  onSelect,
}: {
  integration: Integration
  active: boolean
  onSelect: (path: string) => void
}) {
  return (
    <li>
      <button
        className={'int-item' + (active ? ' active' : '')}
        onClick={() => onSelect(it.path)}
      >
        <SyncAltIcon className="icon int-icon" aria-hidden />
        <span className="int-text">
          <span className="int-name">{it.name}</span>
          <span className="int-path">{it.path}</span>
        </span>
      </button>
    </li>
  )
}

// groupBySystem buckets integrations under their system folder, systems
// sorted alphabetically. Integrations without a system (scaffolded directly
// under the workspace root) come back separately and render at the top level.
function groupBySystem(integrations: Integration[]): {
  systems: { system: string; items: Integration[] }[]
  ungrouped: Integration[]
} {
  const bySystem = new Map<string, Integration[]>()
  const ungrouped: Integration[] = []
  for (const it of integrations) {
    if (!it.system) {
      ungrouped.push(it)
      continue
    }
    const items = bySystem.get(it.system) ?? []
    items.push(it)
    bySystem.set(it.system, items)
  }
  const systems = [...bySystem.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([system, items]) => ({ system, items }))
  return { systems, ungrouped }
}

function initial(name: string): string {
  return name.trim().charAt(0).toUpperCase() || '?'
}

